function openCatalog(pane='definitions') {catalogEpoch++;catalogDraft=copy(catalog);catalogPane=pane;catalogExpanded=null;catalogMenuCache={};catalogMenuSelection={};$('catalog-message').textContent='';catalogEditor();$('catalog-dialog').showModal();}
$('catalog-open').onclick=()=>openCatalog();
function catalogDirty(){const clean=value=>({cuisines:value.cuisines.map(r=>({...r,activityIds:r.activityIds||[]})),brands:value.brands.map(r=>({...r,activityIds:r.activityIds||[]})),profiles:Object.fromEntries(Object.entries(value.profiles).map(([branch,p])=>{const mappings={};for(const kind of ['productCuisineIds','categoryCuisineIds'])mappings[kind]=Object.fromEntries(Object.entries(p[kind]||{}).filter(([,ids])=>ids.length));return [branch,{cuisineIds:p.cuisineIds||[],brandId:p.brandId||null,priceCategoryIds:p.priceCategoryIds||[],...mappings}];}).filter(([,p])=>p.cuisineIds.length||p.brandId||p.priceCategoryIds.length||Object.keys(p.productCuisineIds).length||Object.keys(p.categoryCuisineIds).length))});return !same(clean(catalogDraft),clean(catalog));}
function canCloseCatalog(){return !catalogDirty()||confirm('لديك تغييرات غير محفوظة في الدليل. إغلاق دون حفظ؟');}
$('catalog-close').onclick=()=>{if(!busy&&canCloseCatalog()){catalogEpoch++;$('catalog-dialog').close();}};
async function saveCatalog(toStrip=false){if(busy)return;for(const type of ['cuisines','brands']){if(catalogDraft[type].length>500){$('catalog-message').textContent='الحد الأقصى ٥٠٠ تصنيف لكل نوع؛ احذف الإضافة الزائدة قبل الحفظ.';return;}const labels=catalogDraft[type].map(r=>r.label.trim());if(labels.some(label=>!label||label.length>70)||new Set(labels).size!==labels.length){$('catalog-message').textContent='اكتب أسماء غير فارغة وغير مكررة للتصنيفات والعلامات.';return;}}const payload={baseVersion:catalog.version,cuisines:copy(catalogDraft.cuisines),brands:copy(catalogDraft.brands),profiles:copy(catalogDraft.profiles)};busy=true;for(const control of $('catalog-fields').querySelectorAll('input,button,select'))control.disabled=true;$('catalog-save').disabled=true;$('catalog-to-strip').disabled=true;$('catalog-message').textContent='جارٍ حفظ الدليل والربط…';let saved=false;try{const result=await api('/staff/home-discovery/catalog',payload);catalog={...catalog,version:result.version,cuisines:payload.cuisines,brands:payload.brands,profiles:payload.profiles};saved=true;catalogEpoch++;$('catalog-dialog').close();$('message').textContent='حُفظ دليل التصنيفات والربط؛ يظهر الربط عند تحميل المتجر مجددًا. تعديل الشريط يحتاج حفظ مسودته ونشر الرئيسية.';}catch(e){$('catalog-message').textContent=e.message;}finally{busy=false;$('catalog-save').disabled=false;$('catalog-to-strip').disabled=false;if(!saved)catalogEditor();render();}if(saved&&toStrip)openNavigation('topic',true);else if(saved&&$('navigation-editor').open)navEditor();}
$('catalog-save').onclick=()=>saveCatalog();$('catalog-to-strip').onclick=()=>saveCatalog(true);
$('catalog-dialog').addEventListener('cancel',e=>{if(busy||!canCloseCatalog())e.preventDefault();else catalogEpoch++;});

const navKinds={all:'جميع النتائج',activity:'نوع النشاط',cuisine:'تصنيف الطعام',brand:'العلامة التجارية'};
